import React, {useEffect, useState } from "react"
import Layout from "../components/Layout"
import RssFeedItem from "../components/RssFeedItem"
import BreadCrumb from "../components/BreadCrumb"
import { graphql, Link } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import "../styles/latest.css"; // your CSS file from the previous layout

export default function LatestPage( { data } ) {
  console.log(data )


	const posts = data.allMarkdownRemark.edges;

  return (
   <Layout>
      <BreadCrumb links={["/"]} titles={["Home", "Latest"]} />
    <div className="landing-page">
      {/* Left: post cards */}
      <div className="main-column">
        {posts.map(({ node }) => {
          const image = node.frontmatter.icon
            ? getImage(node.frontmatter.icon)
            : null;

          return (
            <div className="post-card" key={node.id}>
              {image && (
                <GatsbyImage
                  image={image}
                  alt={node.frontmatter.title}
                  style={{ marginBottom: "1rem", borderRadius: "6px" }}
                />
              )}
              <h2>{node.frontmatter.title}</h2>
              <p>{node.excerpt}</p>
              <Link className="read-more" to={node.frontmatter.slug}>
                Read more →
              </Link>
            </div>
          );
        })}
      </div>

      {/* Right: small links */}
      <div className="side-column">
        <h3>Recent Posts</h3>
        <ul className="post-links">
          {posts.map(({ node }) => (
            <li key={node.id}>
              <Link to={node.frontmatter.slug}>{node.frontmatter.title}</Link>
            </li>
          ))}
        </ul>
      </div>
    </div>
   </Layout>
  );
}

export const query = graphql`
  query BlogQuery {
    allMarkdownRemark(
	sort: {frontmatter: {date: DESC}}
      	filter: {frontmatter: { slug: { glob: "*/latest/*" } } }
    ) {
      edges {
        node {
          id
          excerpt(pruneLength: 250)
          frontmatter {
            date(formatString: "Y-MM-DD")
            title
	    slug
          }
        }
      }
    }
  }
`;







